// OQ-14 (S135): intrinsic [width, height] of each /quiz-figures/<basename>.webp, generated by
// scripts/build-quiz-figure-dims.mjs. Given to <img width height> (CSS height: auto) so a figure keeps
// its space before it loads.
import DIMS from "./figureDims.json";

const dims = DIMS as unknown as Record<string, [number, number]>;

export function figureDims(basename: string): [number, number] | undefined {
  return Object.hasOwn(dims, basename) ? dims[basename] : undefined;
}
